public class Partial_with_TriageGen2Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial();
        partial.with(null, 10);
    }

    @Test
    public void testWith_ExistingField_UpdatesValue() {
        // Initialize partial with Year and Month
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandardChronology();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYearOfStandardChronology();

        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType}, new int[]{2020, 1});

        // Change Year from 2020 to 2021
        Partial updated = partial.with(yearType, 2021);

        assertNotSame("Should return a new instance when value changes", partial, updated);
        assertEquals("Year should be updated", 2021, updated.getValue(0));
        assertEquals("Month should remain unchanged", 1, updated.getValue(1));
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandardChronology();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020});

        // Change Year to the same value
        Partial updated = partial.with(yearType, 2020);

        assertSame("Should return the same instance if value is identical", partial, updated);
    }

